export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    // Match root landing and critical landing routes
    if (url.pathname === "/" || url.pathname.startsWith("/tours")) {
      const lcpImage = "/static/hero-dubai-skyline.avif";

      // Stream informational 103 response immediately
      const earlyHints = new Headers({
        Link: `<${lcpImage}>; rel=preload; as=image; type=image/avif; fetchpriority=high`,
      });

      // Dispatch early hints through cloudflare/native edge APIs
      // @ts-ignore
      if (typeof ctx.writeEarlyHints === "function") {
        // @ts-ignore
        ctx.writeEarlyHints(earlyHints);
      }
    }

    // Forward request to SSR Origin (Next.js / Node.js)
    const response = await fetch(request);
    return response;
  },
};

import sharp from "sharp";
import { promises as fs } from "fs";

export async function optimizeLcpHero(inputPath: string, outputPath: string) {
  const buffer = await fs.readFile(inputPath);

  await sharp(buffer)
    .resize({
      width: 1440,
      withoutEnlargement: true,
      fit: "inside",
    })
    .avif({
      quality: 68,
      effort: 7, // High compression effort balance
      chromaSubsampling: "4:2:0",
      lossless: false,
    })
    .toFile(outputPath);
}

import React from "react";

interface HeroProps {
  title: string;
  heroAvifSrc: string;
  fallbackWebpSrc: string;
}

export const CriticalLcpHero: React.FC<HeroProps> = ({
  title,
  heroAvifSrc,
  fallbackWebpSrc,
}) => {
  return (
    <section className="relative w-full min-h-[500px] overflow-hidden bg-neutral-950">
      <picture>
        <source
          type="image/avif"
          srcSet={`${heroAvifSrc}?w=768 768w, ${heroAvifSrc}?w=1440 1440w`}
          sizes="(max-width: 768px) 100vw, 1440px"
        />
        <source
          type="image/webp"
          srcSet={`${fallbackWebpSrc}?w=768 768w, ${fallbackWebpSrc}?w=1440 1440w`}
          sizes="(max-width: 768px) 100vw, 1440px"
        />
        <img
          src={fallbackWebpSrc}
          alt={title}
          // @ts-ignore - React 19 native fetchPriority support
          fetchPriority="high"
          loading="eager"
          decoding="async"
          width={1440}
          height={810}
          className="absolute inset-0 h-full w-full object-cover object-center"
        />
      </picture>
      <div className="relative z-10 p-8 text-white">
        <h1 className="text-4xl font-extrabold tracking-tight">{title}</h1>
      </div>
    </section>
  );
};
